UPDATE "visa_document_template_items" i
SET "instructions" = g.instructions, "updated_at" = now()
FROM "visa_document_templates" t, guidance g
WHERE i."template_id" = t."id" AND t."is_active" = true
  AND t."visa_type_code" = g.visa_type_code AND i."document_key" = g.document_key
  AND coalesce(i."instructions", '') = g.old_instructions;
